import re
import pandas as pd
from datetime import datetime

_NUM_RE = re.compile(r'^[+-]?\d+(\.\d{1,2})?$')
_DATE_RE = re.compile(r'^\d{4}-\d{2}-\d{2}$')

_VALID_CURRENCIES = {'USD', 'EUR', 'GBP'}


def _is_null(v):
    return v is None or (isinstance(v, float) and pd.isna(v)) or pd.isna(v)


def _validate_row(row):
    """Return (reject_reason or None, parsed_dict or None)."""
    payment_id = row['payment_id']
    account_id = row['account_id']
    amount_txt = row['amount_txt']
    currency = row['currency']
    pay_date_txt = row['pay_date_txt']

    # R1 MISSING_ID
    if _is_null(payment_id):
        return 'MISSING_ID', None
    pid_trimmed = str(payment_id).strip()
    if pid_trimmed == '':
        return 'MISSING_ID', None

    # R2 BAD_AMOUNT
    if _is_null(amount_txt):
        return 'BAD_AMOUNT', None
    amt_trimmed = str(amount_txt).strip()
    if not _NUM_RE.match(amt_trimmed):
        return 'BAD_AMOUNT', None
    parsed_amount = float(amt_trimmed)

    # R3 NON_POSITIVE
    if parsed_amount <= 0:
        return 'NON_POSITIVE', None

    # R4 BAD_CURRENCY
    if _is_null(currency):
        return 'BAD_CURRENCY', None
    cur_trimmed = str(currency).strip().upper()
    if cur_trimmed not in _VALID_CURRENCIES:
        return 'BAD_CURRENCY', None

    # R5 BAD_DATE
    if _is_null(pay_date_txt):
        return 'BAD_DATE', None
    date_trimmed = str(pay_date_txt).strip()
    if not _DATE_RE.match(date_trimmed):
        return 'BAD_DATE', None
    try:
        parsed_date = datetime.strptime(date_trimmed, '%Y-%m-%d').date()
    except ValueError:
        return 'BAD_DATE', None

    parsed = {
        'payment_id': pid_trimmed,
        'account_id': account_id,
        'amount': parsed_amount,
        'currency': cur_trimmed,
        'pay_date': parsed_date,
    }
    return None, parsed


def run(inputs: dict) -> dict:
    raw = inputs['raw_payments']

    reject_rows = []
    survivor_rows = []  # list of dicts with row_num and parsed fields

    for _, row in raw.iterrows():
        reason, parsed = _validate_row(row)
        if reason is not None:
            reject_rows.append({'row_num': row['row_num'], 'reject_reason': reason})
        else:
            rec = dict(parsed)
            rec['row_num'] = row['row_num']
            survivor_rows.append(rec)

    # R6 DUPLICATE handling
    valid_rows = []
    if survivor_rows:
        surv_df = pd.DataFrame(survivor_rows)
        surv_df = surv_df.sort_values('row_num', kind='mergesort')
        seen = set()
        for _, r in surv_df.iterrows():
            pid = r['payment_id']
            if pid in seen:
                reject_rows.append({'row_num': r['row_num'], 'reject_reason': 'DUPLICATE'})
            else:
                seen.add(pid)
                valid_rows.append({
                    'payment_id': r['payment_id'],
                    'account_id': r['account_id'],
                    'amount': r['amount'],
                    'currency': r['currency'],
                    'pay_date': r['pay_date'],
                })

    valid_payments = pd.DataFrame(
        valid_rows,
        columns=['payment_id', 'account_id', 'amount', 'currency', 'pay_date']
    )
    payment_rejects = pd.DataFrame(
        reject_rows,
        columns=['row_num', 'reject_reason']
    )

    return {
        'valid_payments': valid_payments,
        'payment_rejects': payment_rejects,
    }
